<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pesanan</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h4 mb-3">Riwayat Pesanan</h1><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Nomor</th><th>Status</th><th>Total</th><th>Tanggal</th><th></th></tr></thead><tbody><?php foreach ($orders as $order): ?><tr><td><?php echo html_escape($order->order_number); ?></td><td><?php echo html_escape($order->status); ?></td><td>Rp <?php echo number_format((float)$order->total,0,',','.'); ?></td><td><?php echo html_escape($order->created_at); ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?php echo site_url('customer/orders/detail/'.$order->id); ?>">Detail</a></td></tr><?php endforeach; ?></tbody></table></div></div></main></body></html>
